/* From Uiverse.io by boryanakrasteva - Tags: form */
.__UIV_SCOPE__ .form {
  width: 250px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  border-radius: 10px;
  padding: 20px 40px;
  background-color: rgba(245, 245, 245, 0.034);
  box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.192);
  transition: .2s linear;
}

.__UIV_SCOPE__ .form button {
  align-self: flex-end;
}

.__UIV_SCOPE__ .form:hover {
  transform: scale(1.1);
}

.__UIV_SCOPE__ .label {
  font-size: 14px;
  margin-bottom: -10.6px;
}

.__UIV_SCOPE__ .input {
  height: 25px;
  width: 100%;
  border: 0.5px solid white;
  background-color: transparent;
  color: white;
  padding: 5px;
  border-radius: 5px;
  transition: .2s linear;
  position: relative;
}

.__UIV_SCOPE__ .input:focus {
  outline: none;
  background-color: rgba(173, 173, 173, 0.233);
  box-shadow: 1px 1px 10px rgba(255, 255, 255, 0.137);
}

.__UIV_SCOPE__ button {
  border: none;
  padding: 4px 10px;
  border-radius: 5px;
  transition: .2s linear;
}

.__UIV_SCOPE__ button:hover {
  background-color: rgba(255, 255, 255, 0.74);
  box-shadow: 2px 2px 10px rgba(124, 124, 124, 0.192);
}
